 28 | export function isWalkable(x, y, objects = OBJECTS) {
 29 |   if (!Number.isFinite(x) || !Number.isFinite(y)) return false;
 30 |   const r = FOUNDER_RADIUS;
 31 |   if (x < r || y < r || x > ROOM.width - r || y > ROOM.depth - r) return false;
 32 |   const pad = 0.05;
 33 |   return !objects.some((o) => x > o.x - pad && x < o.x + o.w + pad && y > o.y - pad && y < o.y + o.d + pad);
 34 | }
