 36 | export function canTravel(from, to, objects = OBJECTS) {
 37 |   const steps = Math.max(1, Math.ceil(Math.hypot(to.x - from.x, to.y - from.y) / 0.07));
 38 |   for (let i = 0; i <= steps; i++) {
 39 |     const t = i / steps;
 40 |     if (!isWalkable(from.x + (to.x - from.x) * t, from.y + (to.y - from.y) * t, objects)) return false;
 41 |   }
 42 |   return true;
 43 | }
