 45 | // A* on a quarter-tile grid, followed by collision-tested line-of-sight smoothing.
 46 | export function nearestWalkable(tx, ty, objects = OBJECTS) {
 47 |   if (isWalkable(tx, ty, objects)) return { x: tx, y: ty };
 48 |   // Spiral outward in quarter-tile steps until we find a walkable point
 49 |   const step = 0.25;
 50 |   for (let r = step; r <= 3; r += step) {
 51 |     let best = null, bestDist = Infinity;
 52 |     const n = Math.ceil((r * 2) / step);
 53 |     for (let i = 0; i <= n; i++) {
 54 |       const t = i / n;
 55 |       for (const [cx, cy] of [
 56 |         [tx - r + t * r * 2, ty - r],
 57 |         [tx + r, ty - r + t * r * 2],
 58 |         [tx + r - t * r * 2, ty + r],
 59 |         [tx - r, ty + r - t * r * 2],
 60 |       ]) {
 61 |         const rx = Math.round(cx / step) * step;
 62 |         const ry = Math.round(cy / step) * step;
 63 |         if (!isWalkable(rx, ry, objects)) continue;
 64 |         const d = Math.hypot(rx - tx, ry - ty);
 65 |         if (d < bestDist) { best = { x: rx, y: ry }; bestDist = d; }
 66 |       }
 67 |     }
 68 |     if (best) return best;
 69 |   }
 70 |   return null;
 71 | }
