207 | export function parseSave(raw) {
208 |   const fresh = newState();
209 |   try {
210 |     const value = JSON.parse(raw);
211 |     if (!value || value.version !== 2) return fresh;
212 |     if (value.founder && isWalkable(value.founder.x, value.founder.y)) fresh.founder = { x: value.founder.x, y: value.founder.y };
213 |     if (Number.isFinite(value.energy)) fresh.energy = Math.max(0, Math.min(100, value.energy));
214 |     if (Number.isFinite(value.minutes)) fresh.minutes = Math.max(540, Math.min(1079, value.minutes));
215 |     if (Number.isFinite(value.distance)) fresh.distance = Math.max(0, Math.min(100000, value.distance));
216 |     if (Array.isArray(value.completed)) fresh.completed = TASKS.filter((id) => value.completed.includes(id));
217 |     fresh.sound = value.sound === true;
218 |     if (Number.isFinite(value.day)) fresh.day = Math.max(1, Math.min(10, value.day));
219 |     return fresh;
220 |   } catch { return fresh; }
221 | }

