305 |   /* ── Character: pixel-art top-down sprite ────────────────────────────── */
306 |   character(founder,dir,moving,time){
307 |     const ctx=this.ctx, S=this.scale, T=TILE_SIZE*S;
308 |     const p=this.sp(founder.x,founder.y);
309 |     const cx=Math.round(p.x+T/2), cy=Math.round(p.y+T/2);
310 | 
311 |     /* walk frame toggles every 180ms */
312 |     const frame=(moving&&!this.reducedMotion)?Math.floor(time/180)%2:0;
313 | 
314 |     /* dominant facing direction */
315 |     const facing=Math.abs(dir.x)>=Math.abs(dir.y)
316 |       ?(dir.x>0?'r':'l')
317 |       :(dir.y>0?'d':'u');
318 | 
319 |     /* helper: draw one "pixel" of the sprite, offset from character center */
320 |     const r=(color,dx,dy,w,h)=>
321 |       px(ctx,color,cx+Math.round(dx*S),cy+Math.round(dy*S),Math.round(w*S)||1,Math.round(h*S)||1);
322 | 
323 |     /* ── ground shadow ── */
324 |     ctx.globalAlpha=0.2; ctx.fillStyle='#000';
325 |     ctx.beginPath();
326 |     ctx.ellipse(cx,cy+Math.round(S*5.5),Math.round(S*4.5),Math.round(S*1.8),0,0,Math.PI*2);
327 |     ctx.fill(); ctx.globalAlpha=1;
328 | 
329 |     /* ── SHOES ── */
330 |     if(facing==='d'||facing==='r'||facing==='l'){
331 |       const f0=frame===0;
332 |       /* left foot forward or back */
333 |       r(C.shoe, -2.5, f0?5.0:4.2, 2.5, 1.6);
334 |       /* right foot opposite */
335 |       r(C.shoe,  0.5, f0?4.2:5.0, 2.5, 1.6);
336 |     } else {
337 |       /* facing up – backs of feet visible */
338 |       r(C.shoe, -2.5, 4.5, 2.2, 1.5);
339 |       r(C.shoe,  0.8, frame===0?4.5:4.0, 2.2, 1.5);
340 |     }
341 | 
342 |     /* ── LEGS ── */
343 |     if(facing==='u'){
344 |       r(C.pantsD, -2.5, 1.5, 2.2, 3.2);
345 |       r(C.pantsD,  0.8, 1.5, 2.2, 3.2);
346 |     } else {
347 |       const f0=frame===0;
348 |       r(C.pants,  -2.5, f0?1.5:2.2, 2.2, f0?3.5:2.8);
349 |       r(C.pants,   0.8, f0?2.2:1.5, 2.2, f0?2.8:3.5);
350 |       /* pant crease highlight */
351 |       r('rgba(255,255,255,0.12)', -2.2, 1.8, 0.8, 2.5);
352 |       r('rgba(255,255,255,0.12)',  1.1, 1.8, 0.8, 2.5);
353 |     }
354 | 
355 |     /* ── BODY / SHIRT ── */
356 |     /* shirt shadow */
357 |     r(C.shirtD, -2.8, -4.5, 6.2, 6.8);
358 |     /* shirt main */
359 |     r(C.shirt, -3.0, -5.0, 6.2, 6.8);
360 |     /* shirt highlight top edge */
361 |     r('rgba(255,255,255,0.18)', -2.5, -5.0, 5.2, 1.5);
362 |     /* collar */
363 |     r(C.skin, -1.0, -5.2, 2.5, 1.8);
364 | 
365 |     /* ── ARMS ── */
366 |     const armOff=(moving&&!this.reducedMotion)?(frame===0?0.8:-0.8):0;
367 |     if(facing!=='u'){
368 |       /* left arm + hand */
369 |       r(C.shirt,  -5.2, -4.2+armOff,  2.2, 4.8);
370 |       r(C.skin,   -5.2,  0.8+armOff,  2.2, 2.0);
371 |       /* right arm + hand */
372 |       r(C.shirt,   3.2, -4.2-armOff,  2.2, 4.8);
373 |       r(C.skin,    3.2,  0.8-armOff,  2.2, 2.0);
374 |     } else {
375 |       r(C.shirt, -5.2, -4.2, 2.2, 4.5);
376 |       r(C.shirt,  3.2, -4.2, 2.2, 4.5);
377 |     }
378 | 
379 |     /* ── NECK ── */
380 |     r(C.skin, -1.0, -5.8, 2.5, 1.5);
381 | 
382 |     /* ── HEAD SHADOW ── */
383 |     r(C.skinD, -3.8, -14.5, 8.2, 9.5);
384 | 
385 |     /* ── HEAD ── */
386 |     r(C.skin, -4.0, -15.0, 8.2, 9.5);
387 | 
388 |     /* ── HAIR ── */
389 |     r(C.hair, -4.0, -15.0, 8.2, 3.0); /* top band */
390 |     if(facing!=='r') r(C.hair, -4.0, -15.0, 1.5, 9.5); /* left side */
391 |     if(facing!=='l') r(C.hair,  2.8, -15.0, 1.5, 9.5); /* right side */
392 |     /* hair shine */
393 |     r('rgba(255,255,255,0.14)', -2.5, -15.0, 3.5, 1.5);
394 | 
395 |     /* ── FACE (only when not facing up) ── */
396 |     if(facing!=='u'){
397 |       /* compute eye positions per facing */
398 |       const eyeLX=facing==='r'?-0.5:(facing==='l'?-2.2:-2.0);
399 |       const eyeRX=facing==='r'? 1.8:(facing==='l'?-0.2: 1.2);
400 |       const eyeY=-9.5;
401 |       /* eye whites */
402 |       r(C.eyeW, eyeLX-0.3, eyeY,     2.8, 2.2);
403 |       r(C.eyeW, eyeRX-0.3, eyeY,     2.8, 2.2);
404 |       /* pupils */
405 |       r(C.eye,  eyeLX+0.2, eyeY+0.5, 1.8, 1.5);
406 |       r(C.eye,  eyeRX+0.2, eyeY+0.5, 1.8, 1.5);
407 |       /* eye shines */
408 |       r('rgba(255,255,255,0.9)', eyeLX+1.0, eyeY+0.3, 0.9, 0.9);
409 |       r('rgba(255,255,255,0.9)', eyeRX+1.0, eyeY+0.3, 0.9, 0.9);
410 |       /* nose */
411 |       r(C.skinD, 0.0, -7.8, 1.2, 1.2);
412 |       /* mouth */
413 |       r(C.skinD, -1.5, -6.0, 3.8, 1.0);
414 |       /* smile corners */
415 |       if(facing==='d'){
416 |         r(C.skinD, -1.5, -6.5, 0.8, 0.8);
417 |         r(C.skinD,  2.0, -6.5, 0.8, 0.8);
418 |       }
419 |     } else {
420 |       /* facing up – show back of head (no face), just ears */
421 |       r(C.skin, -5.0, -12.0, 1.2, 2.5);
422 |       r(C.skin,  4.2, -12.0, 1.2, 2.5);
423 |     }
424 | 
425 |     /* ── NAME TAG ── */
426 |     ctx.save();
427 |     const tagY=cy+Math.round(S*(-19));
428 |     ctx.font='bold '+Math.max(7,Math.round(S*5))+'px "Courier New",monospace';
429 |     ctx.textAlign='center'; ctx.textBaseline='middle';
430 |     const tw=Math.round(ctx.measureText('ALEX').width+S*6), th=Math.round(S*7);
431 |     px(ctx,'rgba(8,12,18,0.85)', cx-Math.round(tw/2), tagY-Math.round(th/2), tw, th);
432 |     ox(ctx,'rgba(100,180,255,0.65)', cx-Math.round(tw/2), tagY-Math.round(th/2), tw, th, 1);
433 |     ctx.fillStyle='#a8d8ff'; ctx.fillText('ALEX',cx,tagY);
434 |     ctx.restore();
435 |   }
