438 |   /* ── Destination marker: single blinking tile (no dashed line) ───────── */
439 |   drawDestMarker(pathArr,time){
440 |     if(!pathArr.length) return;
441 |     const ctx=this.ctx, S=this.scale, T=TILE_SIZE*S;
442 |     const last=pathArr[pathArr.length-1];
443 |     const lp=this.sp(Math.floor(last.x),Math.floor(last.y));
444 |     /* blink between 0.25 and 0.75 opacity */
445 |     const blink=this.reducedMotion?0.6:0.25+Math.sin(time/200)*0.38;
446 |     ctx.globalAlpha=blink;
447 |     px(ctx,C.dest, lp.x, lp.y, T, T);
448 |     ctx.globalAlpha=1;
449 |     /* crisp 1-tile border */
450 |     ox(ctx,C.destRing, lp.x, lp.y, T, T, Math.max(2,S));
451 |     /* small footprint dots inside to make it feel like a marker */
452 |     const fw=Math.round(S*2.5), fh=Math.round(S*2);
453 |     px(ctx,'rgba(255,240,80,0.7)', Math.round(lp.x+T/2-fw/2-S*2), Math.round(lp.y+T/2-fh/2+S), fw, fh);
454 |     px(ctx,'rgba(255,240,80,0.7)', Math.round(lp.x+T/2-fw/2+S*2), Math.round(lp.y+T/2-fh/2-S), fw, fh);
455 |   }
