 46 | // A* on a quarter-tile grid, followed by collision-tested line-of-sight smoothing.
 47 | export function nearestWalkable(tx, ty, objects = OBJECTS) {
 48 |   if (isWalkable(tx, ty, objects)) return { x: tx, y: ty };
 49 |   // Spiral outward in quarter-tile steps until we find a walkable point
 50 |   const step = 0.25;
 51 |   for (let r = step; r <= 3; r += step) {
 52 |     let best = null, bestDist = Infinity;
 53 |     const n = Math.ceil((r * 2) / step);
 54 |     for (let i = 0; i <= n; i++) {
 55 |       const t = i / n;
 56 |       for (const [cx, cy] of [
 57 |         [tx - r + t * r * 2, ty - r],
 58 |         [tx + r, ty - r + t * r * 2],
 59 |         [tx + r - t * r * 2, ty + r],
 60 |         [tx - r, ty + r - t * r * 2],
 61 |       ]) {
 62 |         const rx = Math.round(cx / step) * step;
 63 |         const ry = Math.round(cy / step) * step;
 64 |         if (!isWalkable(rx, ry, objects)) continue;
 65 |         const d = Math.hypot(rx - tx, ry - ty);
 66 |         if (d < bestDist) { best = { x: rx, y: ry }; bestDist = d; }
 67 |       }
 68 |     }
 69 |     if (best) return best;
 70 |   }
 71 |   return null;
 72 | }
