 30 | export function isWalkable(x, y, objects = OBJECTS) {
 31 |   if (!Number.isFinite(x) || !Number.isFinite(y)) return false;
 32 |   const r = FOUNDER_RADIUS;
 33 |   if (x < r || y < r || x > ROOM.width - r || y > ROOM.depth - r) return false;
 34 |   const pad = 0.05;
 35 |   return !objects.some((o) => x > o.x - pad && x < o.x + o.w + pad && y > o.y - pad && y < o.y + o.d + pad);
 36 | }
