 38 | export function canTravel(from, to, objects = OBJECTS) {
 39 |   const steps = Math.max(1, Math.ceil(Math.hypot(to.x - from.x, to.y - from.y) / 0.07));
 40 |   for (let i = 0; i <= steps; i++) {
 41 |     const t = i / steps;
 42 |     if (!isWalkable(from.x + (to.x - from.x) * t, from.y + (to.y - from.y) * t, objects)) return false;
 43 |   }
 44 |   return true;
 45 | }
