 47 | // A* on a quarter-tile grid, followed by collision-tested line-of-sight smoothing.
 48 | export function nearestWalkable(tx, ty, objects = OBJECTS) {
 49 |   if (isWalkable(tx, ty, objects)) return { x: tx, y: ty };
 50 |   // Spiral outward in quarter-tile steps until we find a walkable point
 51 |   const step = 0.25;
 52 |   for (let r = step; r <= 3; r += step) {
 53 |     let best = null, bestDist = Infinity;
 54 |     const n = Math.ceil((r * 2) / step);
 55 |     for (let i = 0; i <= n; i++) {
 56 |       const t = i / n;
 57 |       for (const [cx, cy] of [
 58 |         [tx - r + t * r * 2, ty - r],
 59 |         [tx + r, ty - r + t * r * 2],
 60 |         [tx + r - t * r * 2, ty + r],
 61 |         [tx - r, ty + r - t * r * 2],
 62 |       ]) {
 63 |         const rx = Math.round(cx / step) * step;
 64 |         const ry = Math.round(cy / step) * step;
 65 |         if (!isWalkable(rx, ry, objects)) continue;
 66 |         const d = Math.hypot(rx - tx, ry - ty);
 67 |         if (d < bestDist) { best = { x: rx, y: ry }; bestDist = d; }
 68 |       }
 69 |     }
 70 |     if (best) return best;
 71 |   }
 72 |   return null;
 73 | }
