peptide: {
  icon: 'peptide', eyebrow: 'EXPERIMENTAL PEPTIDE KIT', title: 'High risk, high reward.',
  get description() {
    const chance = Math.min(100, 20 + peptideShots * 20);
    const shots = peptideShots;
    if (shots === 0) return 'An unlabelled vial someone left in the back of the fridge. Full stamina, instantly. The catch: a 20% chance your heart just\u2026 stops. Nobody\u2019s tested these properly.';
    if (shots === 1) return `You\u2019ve already taken one today. The second shot pushes your luck to ${chance}%. Your hands are shaking a little. That\u2019s probably fine.`;
    if (shots === 2) return `Three shots in a day. ${chance}% chance this is the last thing you do. Your vision is slightly blurry. The vial is still very tempting.`;
    if (shots === 3) return `${chance}% chance of death. You\u2019ve already rolled this dice three times today. You can feel your own heartbeat in your teeth.`;
    return `${chance}% chance of death. At this point you\u2019re just seeing what happens. The walls are breathing. This is probably a bad idea.`;
  },
  get detail() {
    const chance = Math.min(100, 20 + peptideShots * 20);
    return `Full stamina instantly \u00b7 \u26A0\uFE0F ${chance}% chance of death`;
  },
  get action() {
    const chance = Math.min(100, 20 + peptideShots * 20);
    if (chance >= 100) return 'Take the shot (certain death \u2620\uFE0F)';
    return `Take the shot (${chance}% risk) \uD83D\uDC89`;
  },
  perform() {
    const chance = Math.min(100, 20 + peptideShots * 20);
    peptideShots += 1;
    if (Math.random() * 100 < chance) {
      peptideDeath();
    } else {
      state.energy = 100;
      toast(`\uD83D\uDC89 It worked. Full stamina. You feel incredible. Probably fine. (${chance}% chance that didn\u2019t happen)`);
      playSound('coffee');
    }
  },
},

